class Store:
    """__enter__ が self ではなく接続を返す（Python のデータモデル: with は __enter__ の戻り値を as に束縛する）"""

    def __init__(self, path: str):
        self.path = path
        self.conn = None

    def __enter__(self):
        self.conn = sqlite3.connect(self.path)
        return self.conn

    def __exit__(self, *exc):
        self.conn.close()


class Workdir:
    """__exit__ が後始末で消す"""

    def __init__(self):
        self.path = "/tmp/work"

    def __enter__(self):
        os.makedirs(self.path, exist_ok=True)
        return self.path

    def __exit__(self, *exc):
        shutil.rmtree(self.path)


class AsyncStore:
    def __init__(self, path: str):
        self.path = path

    async def __aenter__(self):
        return sqlite3.connect(self.path)

    async def __aexit__(self, *exc):
        pass


